import{z as n,x as i,o as e,c as s,q as t,j as l,D as a,d as r,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"上下文管理策略","description":"","frontmatter":{"title":"上下文管理策略","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-context-strategies.md","filePath":"llm/agent-context-strategies.md","lastUpdated":1791063341000}'),m={name:"llm/agent-context-strategies.md"};function C(d,E,p,h,D,c){const A=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="上下文管理策略" tabindex="-1">上下文管理策略 <a class="header-anchor" href="#上下文管理策略" aria-label="Permalink to &quot;上下文管理策略&quot;">​</a></h1><div class="epigraph"><p>轨迹不是越长越好，也不是越短越好；上下文是注意力预算，管理策略决定每个 token 花在哪个任务上。</p><footer>—— 据 Chroma，Context Rot 技术报告（2025）；Anthropic 关于代理上下文工程的博文整理</footer></div><p><a href="/llm/agent-tool-protocol-deep">上一课</a>把动作写成协议事件，其中「结果回填」是轨迹增长的唯一入口。本课管增长本身：<a href="/llm/lc-map">长上下文收束</a>的账本是静态部署的账，代理的账本每个任务自己重演一遍，而且增速由模型自己的行为决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>轨迹单调增长带来三个复合问题。成本上，每一步都重发全部历史，累计输入 token 随步数近似平方增长。<span class="marginnote">数字实例：一个 50 步的任务，每步新增 1000 token，若全量保留，累计输入就是 \\(1000 \\times \\frac{50\\times 51}{2} \\approx 127\\) 万 token——不是 5 万，而是 25 倍。步数翻倍，这笔账翻的不是一倍，是接近四倍。</span>质量上，输入变长后即使任务不难，表现也不稳定——<a href="/llm/context-rot">Context Rot 上下文腐烂</a>把这命名为注意力预算的耗散；中部信息还会被挤到盲区（<a href="/llm/lost-in-middle">Lost in the Middle</a>），第一步定下的约束到第二十步就像没说过。机制上，全量保留会让窗口被工具输出占满，模型反而找不到当前目标。所以策略不是「删不删」，是三个决策：何时触发、保什么、丢什么。做错的方向都很具体：从不压缩，长任务死在预算与腐烂上；乱压缩，关键约束被折叠掉，任务在中途换目标而不自知。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>触发器</strong>：token 阈值、轮数、或任务阶段边界；阈值触发便宜，阶段边界触发更安全。<strong>保留核</strong>：系统提示、未决状态（当前目标、已完成与待办、关键约束）、最近若干轮。<span class="marginnote">直觉类比：保留核就是书桌上的东西——正在做的那份文件（当前目标）、贴在显示器上的便条（关键约束）、手边最近翻过的几页（最近几轮）。其余的进抽屉（摘要）或档案室（落盘句柄），要用再取；而抽屉里的东西你不会每写一句话都重新读一遍。</span><strong>策略谱系</strong>由粗到细：滚动截断最粗暴，丢掉的早期约束不会自己回来；<a href="/llm/compaction-summarize">Compaction 摘要压缩</a>把已完成子任务折叠成摘要；<a href="/llm/structured-memory-compaction">结构化记忆压缩</a>把工具输出抽成字段再存；<a href="/llm/mem1-context">Mem1 递归上下文重写</a>把上下文从存储改成函数——每步按需重写；<a href="/llm/agentfold">AgentFold 上下文折叠</a>按证据价值丢弃中间步骤；<a href="/llm/jit-context-retrieval">Just-in-Time Context Retrieval</a>把工具结果落盘、只回句柄，要用再取。<strong>缓存约束</strong>反着压：<a href="/llm/prompt-cache">Prompt Cache</a> 按前缀命中，压缩改前缀等于缓存全灭；工程解是把稳定段放最前、把可压缩段放后缀，并且只在阶段边界动手。</p>',7)),(e(),l(B,null,{default:a(()=>[o(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%7B%22%E8%BD%A8%E8%BF%B9%E9%95%BF%E5%BA%A6%E6%88%96%E9%98%B6%E6%AE%B5%E8%A7%A6%E5%8F%91%3F%22%7D%20--%3E%7C%22%E5%90%A6%22%7C%20RUN%5B%22%E6%AD%A3%E5%B8%B8%E6%89%A7%E8%A1%8C%E4%B8%80%E6%AD%A5%22%5D%0A%20%20MON%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E9%94%81%E5%AE%9A%E4%BF%9D%E7%95%99%E6%A0%B8%EF%BC%9A%E7%9B%AE%E6%A0%87%E3%80%81%E7%BA%A6%E6%9D%9F%E3%80%81%E6%9C%AA%E5%86%B3%E7%8A%B6%E6%80%81%22%5D%0A%20%20KEEP%20--%3E%20POL%7B%22%E7%AD%96%E7%95%A5%E9%80%89%E6%8B%A9%22%7D%0A%20%20POL%20--%3E%7C%22%E4%BE%BF%E5%AE%9C%22%7C%20TRUNC%5B%22%E6%BB%9A%E5%8A%A8%E6%88%AA%E6%96%AD%22%5D%0A%20%20POL%20--%3E%7C%22%E5%B8%B8%E8%A7%84%22%7C%20SUM%5B%22%E6%91%98%E8%A6%81%E6%8A%98%E5%8F%A0%E5%B7%B2%E5%AE%8C%E6%88%90%E5%AD%90%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20POL%20--%3E%7C%22%E7%BB%86%E7%B2%92%E5%BA%A6%22%7C%20FOLD%5B%22%E6%8C%89%E4%BB%B7%E5%80%BC%E6%8A%98%E5%8F%A0%20%2F%20JIT%20%E5%8F%A5%E6%9F%84%22%5D%0A%20%20TRUNC%20--%3E%20CACHE%5B%22%E6%A3%80%E6%9F%A5%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20SUM%20--%3E%20CACHE%0A%20%20FOLD%20--%3E%20CACHE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「保什么」以未决状态为准：任务是有向图，完成的子任务可以折叠成一行结论，未决分支折叠一行就丢一个出口——摘要丢的不是字，是选择权。为什么关键约束要周期性重述：腐烂发生在中部，重述等于把约束重新搬到注意力的高地，这比指望模型「记得开头」便宜。缓存与压缩的冲突是同一笔账的两面：缓存买的是前缀逐字节稳定的复利，压缩买的是注意力预算；策略的正确形状是分层——系统提示与规则文档（<a href="/llm/agents-md-spec">AGENTS.md 项目规范</a>、<a href="/llm/progressive-disclosure">渐进式披露</a>的加载方式）永远稳定吃缓存，易变的工作集放尾部随时折叠。</p><p><span class="marginnote">多轮前缀命中是复利：<a href="/llm/multi-turn-prefix">多轮前缀命中</a>的机制与 <a href="/llm/kv-prefix-cache">前缀缓存</a>相同——在压缩点之后，所有历史缓存作废，下一步的输入全部重算。把压缩点从「每次都压」改成「阶段边界才压」，缓存命中率的变化是数量级的。</span></p>',3)),(e(),l(B,null,{default:a(()=>[o(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20HEAD%5B%22%E7%A8%B3%E5%AE%9A%E5%8C%BA%EF%BC%88%E5%89%8D%E7%BC%80%EF%BC%89%EF%BC%9A%E6%B0%B8%E8%BF%9C%E9%80%90%E5%AD%97%E8%8A%82%E4%B8%8D%E5%8F%98%22%5D%0A%20%20%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E4%B8%8E%E8%A7%84%E5%88%99%E6%96%87%E6%A1%A3%22%5D%0A%20%20%20%20TOOLS%5B%22%E5%B7%A5%E5%85%B7%E5%AE%9A%E4%B9%89%22%5D%0A%20%20end%0A%20%20subgraph%20TAIL%5B%22%E5%B7%A5%E4%BD%9C%E5%8C%BA%EF%BC%88%E5%90%8E%E7%BC%80%EF%BC%89%EF%BC%9A%E9%9A%8F%E6%97%B6%E5%8F%AF%E6%8A%98%E5%8F%A0%22%5D%0A%20%20%20%20GOAL%5B%22%E5%BD%93%E5%89%8D%E7%9B%AE%E6%A0%87%E4%B8%8E%E5%85%B3%E9%94%AE%E7%BA%A6%E6%9D%9F%EF%BC%88%E5%91%A8%E6%9C%9F%E6%80%A7%E9%87%8D%E8%BF%B0%EF%BC%89%22%5D%0A%20%20%20%20OPEN%5B%22%E6%9C%AA%E5%86%B3%E5%88%86%E6%94%AF%EF%BC%9A%E4%B8%8D%E6%8A%98%E5%8F%A0%22%5D%0A%20%20%20%20DONE%5B%22%E5%B7%B2%E5%AE%8C%E6%88%90%E5%AD%90%E4%BB%BB%E5%8A%A1%EF%BC%9A%E6%8A%98%E5%8F%A0%E6%88%90%E4%B8%80%E8%A1%8C%E6%91%98%E8%A6%81%22%5D%0A%20%20%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E5%B7%A5%E5%85%B7%E8%BE%93%E5%87%BA%EF%BC%9A%E8%90%BD%E7%9B%98%E6%88%96%E6%8A%BD%E5%AD%97%E6%AE%B5%22%5D%0A%20%20end%0A%20%20HEAD%20--%20%22%E5%91%BD%E4%B8%AD%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%EF%BC%8C%E7%9C%81%E9%92%B1%E7%9C%81%E6%97%B6%22%20--%3E%20TAIL%0A%20%20DONE%20--%3E%20SM%5B%22%E6%91%98%E8%A6%81%20%2F%20%E5%8F%A5%E6%9F%84%22%5D%0A%20%20RAW%20--%3E%20SM%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>压缩后细节去哪是<a href="/llm/agent-memory-implementation">记忆系统的实现</a>的问题，本课只管窗口内。<span class="marginnote">常见误区：初学者容易以为压缩只是为了省钱。其实更要紧的是注意力质量——窗口被几千行工具日志占满后，模型经常「看着答案找不到问题」，压掉噪音往往先提准确率、后降成本。</span>提示压缩（<a href="/llm/prompt-compression">提示压缩 LLMLingua</a>）是逐段降速率的技术件，与折叠是互补不是替代。多代理下每个代理各带一份上下文，隔离与传递的规则在<a href="/llm/agent-multi-orchestration">多 Agent 编排模式</a>。显存的静态账不在此重复（<a href="/llm/lc-memory-account">长上下文的显存账</a>已算）；本课是同一笔账在轨迹时间轴上的动态版。没有免费的策略：任何压缩都可能丢掉后来才显出价值的细节，评测要能捕捉这种「丢早了」的失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上下文是注意力预算：轨迹管理的目标是把预算花在未决状态上，不是堆历史。</li><li>触发器、保留核、策略谱系三个决策分开定；阈值触发便宜，阶段边界更安全。</li><li>关键约束周期性重述，抵消中部遗忘；完成子任务折叠，未决分支不折叠。</li><li>缓存买前缀稳定，压缩买注意力；分层摆放让两者共存。</li><li>压缩有损且不可逆，评测必须能捕捉「丢早了」。</li><li>出处：据 Chroma Context Rot 报告（2025）与 Mem1、AgentFold 等方法的公开口径整理。</li></ul>',4))])}const _=n(m,[["render",C]]);export{f as __pageData,_ as default};
